svg.script:

(() => {
    const orbitGroup = document.getElementById('orbitGroup');

    if (!orbitGroup) {
        return;
    }

    const reducedMotion = window.matchMedia(
        '(prefers-reduced-motion: reduce)'
    );

    const centreX = 110;
    const centreY = 110;

    /*
     * Duration of one complete round.
     * Increase for slower movement.
     */
    const duration = 2500;

    /*
     * Controls how strongly the text slows at the top.
     *
     * 0    = constant speed
     * 0.3  = subtle slowdown
     * 0.55 = noticeable, smooth slowdown
     * 0.8  = strong slowdown
     *
     * Keep this below 1.
     */
    const slowdownStrength = 0.8;

    let animationFrame = null;
    let startedAt = null;

    const render = (timestamp) => {
        if (reducedMotion.matches) {
            orbitGroup.setAttribute(
                'transform',
                `rotate(180 ${centreX} ${centreY})`
            );

            animationFrame = null;
            startedAt = null;

            return;
        }

        if (startedAt === null) {
            startedAt = timestamp;
        }

        const elapsed = timestamp - startedAt;
        const progress = (elapsed % duration) / duration;

        const phase = progress * Math.PI * 2;

        const adjustedPhase =
            phase
            - slowdownStrength * Math.sin(phase);

        const rotation =
            180
            + adjustedPhase * 180 / Math.PI;

        orbitGroup.setAttribute(
            'transform',
            `rotate(${rotation} ${centreX} ${centreY})`
        );

        animationFrame = requestAnimationFrame(render);
    };

    const startAnimation = () => {
        if (animationFrame !== null) {
            cancelAnimationFrame(animationFrame);
        }

        animationFrame = null;
        startedAt = null;

        if (reducedMotion.matches) {
            orbitGroup.setAttribute(
                'transform',
                `rotate(180 ${centreX} ${centreY})`
            );

            return;
        }

        animationFrame = requestAnimationFrame(render);
    };

    reducedMotion.addEventListener(
        'change',
        startAnimation
    );

    startAnimation();
})();
